@startuml

class Researcher {
  + name : string
  + surname : string
  + isAvailable : boolean
  + checkAvailable() : boolean
  + assignToTeam(team) : void
}

class SeniorResearcher extends Researcher {}

class JuniorResearcher extends Researcher {}

class Team {
  + name : string
}

class Area {
  + name : string
}

class AreaManager {
  + name : string
  + surname : string
}

class Project {
  + name : string
}

Area "1" -- "1" AreaManager : has
Area "1" *-- "1..*" Team : grouped into
Team "1" -- "1" SeniorResearcher : led by
Team "1" -- "1..*" JuniorResearcher : includes
Team "1" -- "1" Project : carries out
Researcher "1..*" -- "1" Area : belongs to

@enduml

